function coveringWindow(s: string, t: string): string {
  const base = new Map<string, number>();
  for (const c of t) base.set(c, (base.get(c) ?? 0) + 1);
  let bestStart = 0, bestLen = Infinity;
  for (let i = 0; i < s.length; i++) {
    const need = new Map(base);
    let missing = t.length;
    for (let j = i; j < s.length && j - i + 1 < bestLen; j++) {
      const left = need.get(s[j]);
      if (left === undefined) continue;
      if (left > 0) missing--;
      need.set(s[j], left - 1);
      if (missing === 0) {
        bestStart = i;
        bestLen = j - i + 1;
        break;
      }
    }
  }
  return bestLen === Infinity ? "" : s.slice(bestStart, bestStart + bestLen);
}

