class Solution:
    def coveringWindow(self, s: str, t: str) -> str:
        base = Counter(t)
        best_start, best_len = 0, math.inf
        for i in range(len(s)):
            need = dict(base)
            missing = len(t)
            for j in range(i, len(s)):
                if j - i + 1 >= best_len:
                    break
                c = s[j]
                if c not in need:
                    continue
                if need[c] > 0:
                    missing -= 1
                need[c] -= 1
                if missing == 0:
                    best_start, best_len = i, j - i + 1
                    break
        return "" if best_len == math.inf else s[best_start:best_start + best_len]

