function coveringWindow(s: string, t: string): string {
  const need = new Map<string, number>();
  for (const c of t) need.set(c, (need.get(c) ?? 0) + 1);
  let missing = t.length; // characters of t, with repeats, not yet in the window
  let bestStart = 0, bestLen = Infinity, start = 0;
  for (let end = 0; end < s.length; end++) {
    const c = s[end];
    if (need.has(c)) {
      if (need.get(c)! > 0) missing--;
      need.set(c, need.get(c)! - 1);
    }
    while (missing === 0) {
      if (end - start + 1 < bestLen) { // strict: keep the leftmost on ties
        bestLen = end - start + 1;
        bestStart = start;
      }
      const d = s[start];
      if (need.has(d)) {
        need.set(d, need.get(d)! + 1);
        if (need.get(d)! > 0) missing++;
      }
      start++;
    }
  }
  return bestLen === Infinity ? "" : s.slice(bestStart, bestStart + bestLen);
}

